function AutoWalkEnterVolume:__init()
    self.controller = nil
end


function AutoWalkEnterVolume:__delete()
end


function AutoWalkEnterVolume:Init( autoWalk_ )
    KTool.SetActive(self.controller.gameObject, true)


    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
    end

    self.transform = self.controller.gameObject.transform

    assert( isNotNull(KTool.GetComponent(self.controller.gameObject, typeof(Collider))) )

    self.autoWalk = autoWalk_


end



function AutoWalkEnterVolume:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


---@return void
---@param other_ UnityEngine.Collider
function AutoWalkEnterVolume:OnTriggerEnter(other_)
    self.autoWalk:Enter( other_ )
end



